        rs=[y for y,x in comp]; cs=[x for y,x in comp]
        r0,r1=min(rs),max(rs); c0,c1=min(cs),max(cs)
        area=(r1-r0+1)*(c1-c0+1)
        if r1>r0 and c1>c0 and len(comp)>=3 and len(comp)/area>=0.5:
          for y in range(r0,r1+1):
            for x in range(c0,c1+1): out[y][x]=col
    for r in range(h):
      for c in range(w):
        if g[r][c]!=bg and out[r][c]==g[r][c] and g[r][c] not in [g[r][c]]: pass
    # Any original non-background pixel not assigned to accepted rectangle is noise.
    accepted={(r,c) for r in range(h) for c in range(w) if out[r][c]!=bg}
    for r in range(h):
      for c in range(w):
        if g[r][c]!=bg and (r,c) not in accepted: out[r][c]=bg
    return out
